`timescale 1ns/1ps
module vector_stage12_benchmark_tb #(parameter integer LOOKAHEAD_DEPTH=6);
 logic clk=0,rst=0,start=0; always #5 clk=~clk; logic [4:0] program_length; logic running,done; logic [3:0] current_pc; logic [15:0] current_instruction; logic current_instruction_valid;
 logic pe=0; logic [3:0] pa; logic [15:0] pd; logic de=0; logic [4:0] da; logic [127:0] dd; logic dre=0; logic [4:0] dra; logic [127:0] drd;
 logic ve=0; logic [2:0] va; logic [127:0] vd; logic re=0; logic [2:0] ra; logic [127:0] rd; logic [2:0] state_dbg;
 logic [31:0] req,hit,miss,e0h,e1h,oa,os,dep,e0f,e1f,dup,ar,aph; logic [31:0] orhw,c2,second,p0sd,p1sd,pair,dreq,dhit,maxdist; logic ev0,ev1,ep; logic [4:0] ea0,ea1; logic [127:0] ed0,ed1; integer max_valid=0,fail=0; integer valid_now;
 vector_two_outstanding_prefetch_program_core #(.LOOKAHEAD_DEPTH(LOOKAHEAD_DEPTH)) dut(.clk(clk),.rst(rst),.start(start),.program_length(program_length),.running(running),.done(done),.current_pc(current_pc),.current_instruction(current_instruction),.current_instruction_valid(current_instruction_valid),.prog_load_enable(pe),.prog_load_addr(pa),.prog_load_data(pd),.data_load_enable(de),.data_load_addr(da),.data_load_data(dd),.data_debug_read_enable(dre),.data_debug_read_addr(dra),.data_debug_read_data(drd),.vector_load_enable(ve),.vector_load_addr(va),.vector_load_data(vd),.debug_read_enable(re),.debug_read_addr(ra),.debug_read_data(rd),.state_debug(state_dbg),.prefetch_request_count(req),.prefetch_hit_count(hit),.prefetch_miss_count(miss),.entry0_hit_count(e0h),.entry1_hit_count(e1h),.overlap_alu_count(),.overlap_store_count(os),.dependency_blocked_count(dep),.entry0_fill_count(e0f),.entry1_fill_count(e1f),.duplicate_suppression_count(dup),.alu_read_overlap_count(ar),.alu_prefetch_hit_count(aph),.debug_entry0_valid(ev0),.debug_entry1_valid(ev1),.debug_entry0_addr(ea0),.debug_entry1_addr(ea1),.debug_entry0_data(ed0),.debug_entry1_data(ed1),.debug_pending_read_valid(ep),.outstanding_read_high_watermark(orhw),.cycles_with_two_outstanding(c2),.second_request_while_first_pending_count(second),.pending0_stale_discard_count(p0sd),.pending1_stale_discard_count(p1sd),.two_outstanding_useful_pair_count(pair),.deep_prefetch_request_count(dreq),.deep_prefetch_hit_count(dhit),.max_lookahead_distance(maxdist));
 always @(posedge clk) begin #1; valid_now=(dut.debug_entry0_valid?1:0)+(dut.debug_entry1_valid?1:0); if(valid_now>max_valid) max_valid=valid_now; end
 function automatic [127:0] p4(input [31:0]a,b,c,d);p4={d,c,b,a};endfunction function automatic [15:0] alu(input [3:0]o,input [2:0]d,a,b);alu={o,d,a,b,3'b0};endfunction function automatic [15:0] ld(input [2:0]d,input [4:0]a);ld={4'ha,d,a,4'b0};endfunction function automatic [15:0] st(input [2:0]s,input [4:0]a);st={4'hb,s,a,4'b0};endfunction
 task automatic rst_core;begin rst=1;@(posedge clk);#1;rst=0;end endtask task automatic li(input int a,input [15:0]x);begin pa=a;pd=x;pe=1;@(posedge clk);#1;pe=0;end endtask task automatic lm(input [4:0]a,input [127:0]x);begin da=a;dd=x;de=1;@(posedge clk);#1;de=0;end endtask task automatic lv(input [2:0]a,input [127:0]x);begin va=a;vd=x;ve=1;@(posedge clk);#1;ve=0;end endtask
 task automatic run(input int n,output int cyc);integer k;begin max_valid=0;program_length=n;start=1;@(posedge clk);#1;start=0;cyc=0;while(!done&&cyc<300)begin@(posedge clk);#1;cyc++;end if(!done)begin fail++;$display("FAIL timeout");end end endtask
 task automatic read_mem(input [4:0]a,input [127:0]e);begin dra=a;dre=1;@(posedge clk);#1;if(drd!==e)begin fail++;$display("FAIL memory[%0d] exp=%h got=%h",a,e,drd);end dre=0;end endtask
 task automatic print_bench(input string n,input int cyc,input int ops,input int alus);begin $display("BENCH %s CYCLES=%0d CYCLES_PER_VECTOR=%0.6f CYCLES_PER_SCALAR=%0.6f OPS_PER_CYCLE=%0.6f ALU_FRACTION=%0.6f",n,cyc,real'(cyc)/4,real'(cyc)/ops,real'(ops)/cyc,real'(alus)/cyc);$display("COUNTER %s ALU_READ_OVERLAP=%0d ALU_ORIGIN_HIT=%0d STORE_READ_OVERLAP=%0d PREFETCH_REQUESTS=%0d PREFETCH_HITS=%0d MAX_VALID_ENTRIES=%0d OUTSTANDING_HIGH=%0d SECOND_WHILE_PENDING=%0d TWO_OUTSTANDING_CYCLES=%0d TWO_USEFUL_PAIRS=%0d",n,ar,aph,os,req,hit,max_valid,orhw,second,c2,pair);end endtask
 initial begin logic[127:0]a,b,mask,e;integer cyc;a=p4(1,2,3,4);b=p4(5,6,7,8);mask=p4(32'hffff0000,32'h0000ffff,32'h00ff00ff,32'hff00ff00);
  rst_core;lv(1,a);lv(2,b);li(0,alu(0,3,1,2));li(1,alu(0,4,3,2));li(2,alu(0,5,4,2));li(3,alu(0,6,5,2));run(4,cyc);print_bench("REG_VADD",cyc,16,4);
  rst_core;for(int i=0;i<4;i++)begin lm(i,p4(i+1,i+2,i+3,i+4));lm(8+i,p4(10+i,20+i,30+i,40+i));li(4*i,ld(1,i));li(4*i+1,ld(2,8+i));li(4*i+2,alu(0,3,1,2));li(4*i+3,st(3,16+i));end run(16,cyc);for(int i=0;i<4;i++)begin e=p4((i+1)+(10+i),(i+2)+(20+i),(i+3)+(30+i),(i+4)+(40+i));read_mem(16+i,e);end print_bench("ARRAY_ADD",cyc,16,4);
  rst_core;lv(2,mask);for(int i=0;i<4;i++)begin lm(i,p4(i,i+1,i+2,i+3));li(3*i,ld(1,i));li(3*i+1,alu(4,3,1,2));li(3*i+2,st(3,16+i));end run(12,cyc);print_bench("XOR",cyc,16,4);
  rst_core;lv(2,p4(1,1,1,1));for(int i=0;i<4;i++)begin lm(i,p4(32'h80000000+i,32'h1,32'hffffffff,32'h7fffffff));li(3*i,ld(1,i));li(3*i+1,alu(9,3,1,2));li(3*i+2,st(3,16+i));end run(12,cyc);print_bench("VSRA",cyc,16,4);
  if(fail==0)$display("VECTOR STAGE12 BENCHMARK TEST PASSED");else $display("VECTOR STAGE11 BENCHMARK TEST FAILED failures=%0d",fail);$finish;
 end
endmodule


